//! Differential tests: replay Python-generated vectors through the Rust port.
//!
//! Vectors live in `tests/vectors/vectors.json`, generated by
//! `tools/dump_vectors.py` from the `aim.py` reference. Float outputs use
//! identical IEEE-754 op order on both sides, so coordinates compare exactly;
//! only pre-sorted, clear-margin orderings are used (no near-ties).

use aim_rs::{aim_step, headshot_offset, reject_own, select_locked, select_target, smooth_move, Det, Kalman2D};
use serde::Deserialize;

const VECTORS: &str = include_str!("vectors/vectors.json");

#[derive(Debug, Deserialize)]
struct Case {
    kind: String,
    name: String,
    input: serde_json::Value,
    expected: serde_json::Value,
}

#[derive(Debug, Deserialize)]
struct SelectIn {
    dets: Vec<[f64; 6]>,
    cw: f64,
    ch: f64,
    center: bool,
    last: Option<[f64; 2]>,
    sticky_px: f64,
    fov: Option<[f64; 2]>,
    max_box_h: f64,
}

#[derive(Debug, Deserialize)]
struct SmoothIn {
    dx: f64,
    dy: f64,
    smooth: f64,
    max_step: i64,
    deadzone: f64,
}

#[derive(Debug, Deserialize)]
struct OffsetIn {
    h: f64,
    headshot_mode: bool,
}

#[derive(Debug, Deserialize)]
struct KleadIn {
    zs: Vec<[f64; 2]>,
    dt: f64,
    r: f64,
    qx: f64,
    qy: f64,
    gate: f64,
    t_lead: f64,
    vmax: f64,
}

#[derive(Debug, Deserialize)]
struct OwnIn {
    dets: Vec<[f64; 6]>,
    w: f64,
    h: f64,
    edge: f64,
    corner: bool,
    sides: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct LockedTgt {
    x: f64,
    y: f64,
    h: f64,
    tid: Option<i64>,
}

#[derive(Debug, Deserialize)]
struct LockedExp {
    tgt: Option<LockedTgt>,
    lock: Option<i64>,
}

#[derive(Debug, Deserialize)]
struct LockedIn {
    dets: Vec<[f64; 6]>,
    ids: Vec<Option<i64>>,
    locked: Option<i64>,
    cw: f64,
    ch: f64,
    center: bool,
    last: Option<[f64; 2]>,
    sticky_px: f64,
    fov: Option<[f64; 2]>,
    max_box_h: f64,
    min_conf: f64,
}

#[derive(Debug, Deserialize)]
struct ChainIn {
    dets: Vec<[f64; 6]>,
    cw: f64,
    ch: f64,
    center: bool,
    last: Option<[f64; 2]>,
    sticky_px: f64,
    fov: Option<[f64; 2]>,
    max_box_h: f64,
    headshot_mode: bool,
    amp: f64,
    smooth: f64,
    max_step: i64,
    deadzone: f64,
}

#[derive(Debug, Deserialize)]
struct ChainExp {
    mv: Option<[i64; 2]>,
    last: Option<[f64; 2]>,
}

fn to_dets(rows: &[[f64; 6]]) -> Vec<Det> {
    rows.iter()
        .map(|r| Det {
            x1: r[0],
            y1: r[1],
            x2: r[2],
            y2: r[3],
            conf: r[4],
            cls: r[5],
        })
        .collect()
}

#[test]
fn differential_vectors() {
    let cases: Vec<Case> = serde_json::from_str(VECTORS).expect("parse vectors.json");
    assert!(!cases.is_empty(), "no vectors found");
    for c in &cases {
        match c.kind.as_str() {
            "select" => {
                let inp: SelectIn = serde_json::from_value(c.input.clone()).unwrap();
                let exp: Option<[f64; 3]> =
                    serde_json::from_value(c.expected.clone()).unwrap();
                let dets = to_dets(&inp.dets);
                let got = select_target(
                    &dets,
                    inp.cw,
                    inp.ch,
                    inp.center,
                    inp.last.map(|l| (l[0], l[1])),
                    inp.sticky_px,
                    inp.fov.map(|f| (f[0], f[1])),
                    inp.max_box_h,
                );
                assert_eq!(
                    got.map(|(x, y, h)| [x, y, h]),
                    exp,
                    "select/{}",
                    c.name
                );
            }
            "smooth" => {
                let inp: SmoothIn = serde_json::from_value(c.input.clone()).unwrap();
                let exp: [i64; 2] = serde_json::from_value(c.expected.clone()).unwrap();
                let got = smooth_move(inp.dx, inp.dy, inp.smooth, inp.max_step, inp.deadzone, 0.0, 0);
                assert_eq!(got, (exp[0], exp[1]), "smooth/{}", c.name);
            }
            "klead" => {
                let inp: KleadIn = serde_json::from_value(c.input.clone()).unwrap();
                let exp: [f64; 2] = serde_json::from_value(c.expected.clone()).unwrap();
                let mut k = Kalman2D::new(inp.zs[0][0], inp.zs[0][1], 25.0, 900.0, inp.qx, inp.qy);
                for z in inp.zs.iter().skip(1) {
                    k.predict(inp.dt);
                    k.update(z[0], z[1], inp.r, inp.gate);
                }
                let got = k.ahead(inp.t_lead, inp.vmax);
                assert_eq!([got.0, got.1], exp, "klead/{}", c.name);
            }
            "own" => {
                let inp: OwnIn = serde_json::from_value(c.input.clone()).unwrap();
                let exp: Vec<bool> = serde_json::from_value(c.expected.clone()).unwrap();
                let dets = to_dets(&inp.dets);
                let got = reject_own(
                    &dets, inp.w, inp.h, inp.edge, inp.corner,
                    inp.sides.iter().any(|s| s == "left"),
                    inp.sides.iter().any(|s| s == "right"),
                );
                assert_eq!(got, exp, "own/{}", c.name);
            }
            "locked" => {
                let inp: LockedIn = serde_json::from_value(c.input.clone()).unwrap();
                let exp: LockedExp = serde_json::from_value(c.expected.clone()).unwrap();
                let dets = to_dets(&inp.dets);
                let ids: Vec<i64> = inp.ids.iter().map(|o| o.unwrap_or(-1)).collect();
                let (t, lock) = select_locked(
                    &dets,
                    &ids,
                    inp.locked,
                    inp.cw,
                    inp.ch,
                    inp.center,
                    inp.last.map(|l| (l[0], l[1])),
                    inp.sticky_px,
                    inp.fov.map(|f| (f[0], f[1])),
                    inp.max_box_h,
                    inp.min_conf,
                );
                let got_tgt = t.map(|(x, y, h, tid)| LockedTgt { x, y, h, tid });
                assert_eq!(got_tgt.map(|g| (g.x, g.y, g.h, g.tid)), exp.tgt.map(|e| (e.x, e.y, e.h, e.tid)), "locked/{}/tgt", c.name);
                assert_eq!(lock, exp.lock, "locked/{}/lock", c.name);
            }
            "chain" => {
                let inp: ChainIn = serde_json::from_value(c.input.clone()).unwrap();
                let exp: ChainExp = serde_json::from_value(c.expected.clone()).unwrap();
                let dets = to_dets(&inp.dets);
                let (mv, last) = aim_step(
                    &dets,
                    inp.cw,
                    inp.ch,
                    inp.center,
                    inp.last.map(|l| (l[0], l[1])),
                    inp.sticky_px,
                    inp.fov.map(|f| (f[0], f[1])),
                    inp.max_box_h,
                    inp.headshot_mode,
                    inp.amp,
                    inp.smooth,
                    inp.max_step,
                    inp.deadzone,
                );
                assert_eq!(
                    mv,
                    exp.mv.map(|m| (m[0], m[1])),
                    "chain/{}/mv",
                    c.name
                );
                assert_eq!(
                    last.map(|(x, y)| [x, y]),
                    exp.last,
                    "chain/{}/last",
                    c.name
                );
            }
            "offset" => {
                let inp: OffsetIn = serde_json::from_value(c.input.clone()).unwrap();
                let exp: f64 = serde_json::from_value(c.expected.clone()).unwrap();
                let got = headshot_offset(inp.h, inp.headshot_mode);
                assert_eq!(got, exp, "offset/{}", c.name);
            }
            other => panic!("unknown vector kind: {other}"),
        }
    }
    println!("replayed {} vectors", cases.len());
}

/// Jitter is intentionally a different stream than CPython's: assert the
/// contract instead — deterministic per seed, bounded by the jitter radius.
#[test]
fn jitter_contract() {
    let base = smooth_move(100.0, -50.0, 2.0, 1000, 0.0, 0.0, 0);
    let a = smooth_move(100.0, -50.0, 2.0, 1000, 0.0, 5.0, 42);
    let b = smooth_move(100.0, -50.0, 2.0, 1000, 0.0, 5.0, 42);
    assert_eq!(a, b, "same seed must give same output");
    assert!(
        ((a.0 - base.0) as f64).abs() <= 6.0 && ((a.1 - base.1) as f64).abs() <= 6.0,
        "jitter must stay within radius+rounding: base={base:?} got={a:?}"
    );
    // jitter=0 ignores the seed entirely
    assert_eq!(
        smooth_move(100.0, -50.0, 2.0, 1000, 0.0, 0.0, 1),
        smooth_move(100.0, -50.0, 2.0, 1000, 0.0, 0.0, 999),
    );
}
